var email = "Hi, order 1042 arrived broken. I would like a refund. Sara";

// Step 1 (a model call in real code): extract the facts as structured data.
var facts = Extract(email);
Console.WriteLine($"1. Facts: order={facts.Order}, problem={facts.Problem}, wants={facts.Wants}");

// Step 2 (plain C#): the business rule is never left to the model.
var allowed = facts.Problem == "broken" && facts.Wants == "refund";
Console.WriteLine($"2. Policy: refund allowed = {allowed}");

// Step 3 (a model call in real code): write the reply from the checked decision.
var reply = allowed
    ? $"Sorry about order {facts.Order}. Your refund is on its way."
    : "Thanks for writing. A colleague will contact you today.";
Console.WriteLine($"3. Reply: {reply}");

static (string Order, string Problem, string Wants) Extract(string text) =>
    (text.Split(' ').First(w => w.Length == 4 && w.All(char.IsDigit)),
     text.Contains("broken") ? "broken" : "other",
     text.Contains("refund") ? "refund" : "other");

