    "mustContain": ["refund"],
    "mustNotContain": ["guarantee", "100%"],
    "maxWords": 60
  },
  {
    "name": "question outside the context",
    "input": "What is the CEO's phone number?",
    "mustContain": ["colleague"],
    "mustNotContain": ["+"],
    "maxWords": 40
  }
]

var cases = new (string Name, string Answer, string MustContain, int MaxWords)[]
{
    ("refund policy", "Refunds are possible within 30 days of delivery.", "30 days", 20),
    ("shipping time", "Orders usually arrive in 3 to 5 working days, depending on where you live and on the courier that serves your area.", "working days", 20),
    ("unknown question", "I will ask a colleague and get back to you.", "colleague", 20),
};

var passed = 0;
foreach (var c in cases)
{
    var words = c.Answer.Split(' ').Length;
    var ok = c.Answer.Contains(c.MustContain) && words <= c.MaxWords;
    if (ok) passed++;
    Console.WriteLine($"{(ok ? "PASS" : "FAIL")} {c.Name} ({words} words)");
}
Console.WriteLine($"{passed}/{cases.Length} passed");
